    "notes": "【岗位职责】\n1. 客户需求挖掘与对接：常态化对接合作直客、重点行业大客户，开展日常沟通与需求调研，深度理解客户进出口运输、跨境供应链、仓储配送等个性化业务诉求。\n2. 综合物流方案落地与服务跟进：配合业务团队为客户提供定制化综合物流解决方案服务支撑，全程跟进方案执行全流程，对接内部及外部合作资源，实时把控关键节点，保障方案高效落地，根据客户反馈持续优化服务流程，满足客户对时效、成本、服务质量的综合要求。\n3. 服务流程优化与数字化提质增效：熟练运用公司各类业务系统、数字化服务工具开展客户服务工作，常态化梳理大客户服务过程中的业务痛点、流程堵点、高频问题。结合数字化工具与标准化服务思维，协助提升整体客服工作效率与服务专业度，助力公司供应链服务品牌升级。\n\n【任职资格】\n1、大学本科及以上学历应届毕业生；\n2、供应链/物流/交通运输相关专业、计算机相关专业、市场营销、经济学、外语专业优先；\n3、有较强的服务意识、沟通协调能力、理解能力、决策能力。有较强的责任感，人际关系和谐，工作严谨细心，条理性好，顾全大局，具有高度的团队合作精神;\n4、具有较好的英语读写能力和数字化工具使用能力，熟悉office等办公软件应用。\n5.岗位工作地点包含福建省内网点，将结合公司业务发展统筹调配，入职后需服从公司岗位及驻地安排。",
