    "notes": "岗位职责：\n1.负责储能箱/集装箱整体结构方案设计，包括箱体框架、底板、顶板、侧壁、门体、吊装点、堆码及运输固定结构等；\n2.负责箱内电池架、PCS、配电柜、温控机组、消防设备等部件的承载与安装结构设计，完成3D建模、2D图纸、BOM及结构件选型；\n3.负责储能箱防护与安全结构设计，包括防尘防水（IP54/IP55及以上）、防腐、隔热、保温、通风、密封及防火分隔等；\n4.负责结构强度、刚度、抗震、抗风、吊装、运输、雪载等工况的校核与优化，使用ANSYS、Abaqus等CAE工具进行仿真分析；\n5.编制结构设计规范、技术协议、安装说明书等技术文件；\n6.与电气、热管理、消防、舾装等专业协同，完成集装箱式储能系统的集成设计；\n7.跟踪储能行业相关标准，船级社规范（如适用）。\n任职要求：\n1.硕士及以上学历；机械类（机械工程、机械设计制造及其自动化、机械电子工程、材料成型及控制工程、过程装备与控制工程、机电一体化）；力学类（工程力学、固体力学、流体力学等相关专业）；电气类（电气工程、电力系统、自动化、电力电子等）；其他：储能科学与工程、车辆工程等相关专业。\n2.熟练使用至少一种2D/3D设计软件（如中望CAD、AutoCAD、SolidWorks、UG/NX、CATIA、Creo等）；具备CAE仿真基础者优先（ANSYS、Abaqus、FloEFD等），能完成结构强度、振动、散热等仿真分析；\n3.具备扎实的力学基础（材料力学、结构力学、有限元分析等）；了解钣金、压铸等常见加工工艺，熟悉结构设计相关的安规、散热基础常识；了解储能系统基本架构（PCS、BMS、EMS）及工作原理者优先。\n4.具备储能箱、集装箱、预制舱结构设计，构力学、有限元分析、产品设计等相关实习或项目经历，或储能、电力电子行业相关实习经验者优先；\n5.熟悉储能箱防护、防火、防腐、密封、吊装运输等设计规范者优先；\n6.在校期间有新能源/储能企业实习经历，或有相关创新创业大赛、科研项目经验者优先。\n7.具备基础的项目对接能力，能协助处理生产现场的结构相关问题；\n8.具备良好的系统思维能力和学习意愿，善于跨专业沟通协作（电气/结构/软件/项目）；\n9.具备较强的沟通、协调、书面表达及执行能力；\n10.大学英语四级以上或相当水平，具备一定的英文文献阅读能力。",
