    "examInfo": "",
    "companyScale": "30000人以上",
    "notes": "<div style=\"white-space: normal;\"><p style=\"margin-bottom: 0px; margin-top: 0px;\"><strong>【岗位介绍】</strong></p>\n<p>&ldquo;蔚蓝计划&rdquo;是中国远洋海运集团管理培训生计划，是集团根据战略发展需要，建设具有国际竞争力的世界一流航运科技企业的举措，为推动集团高质量发展做好人才储备。此次招聘是中国远洋海运集团招收的第七批集团管培生。</p>\n<p><strong>【计划目标】</strong></p>\n<p>通过集团&ldquo;蔚蓝计划&rdquo;，聚焦培养&ldquo;企业未来改革创新发展中坚力量&rdquo;的目标任务，努力打造一支具有较强开拓创新精神，能够快速接受新鲜事物，熟悉全球商业运作模式，与世界一流航运科技企业相匹配的专业人才队伍。</p>\n<p><strong>【基本任职要求】</strong></p>\n<p>1.大学本科及以上学历；</p>\n<p>2.境内院校应届毕业生需于2027年8月1日前取得毕业证书，境外院校应届毕业生需于2027年12月31日前取得毕业证书；</p>\n<p>3.责任心、事业心强，有良好的职业道德和政治素质；</p>\n<p>4.能接纳并融入集团公司的企业文化，尊重和认同集团公司的核心价值观；</p>\n<p>5.学习和逻辑能力强，积极向上；</p>\n<p>6.富有团队精神和沟通协作意识，理智客观；</p>\n<p>7.敢于接受挑战，做事持之以恒；</p>\n<p>8.有较好的外语听说读写能力和文字写作水平；</p>\n<p>9.遵纪守法、诚实守信、作风正派、身心健康，无不良记录。</p>\n<p><strong>【加分条件】</strong></p>\n<p>（符合下述一项或多项条件可为简历加分）</p>\n<p>1.博士研究生毕业且具备较为丰富的科研工作经历；</p>\n<p>2.&ldquo;强基计划&rdquo;相关专业背景；</p>\n<p>3.具备数字化、绿色低碳等科技创新项目的建设经验；</p>\n<p>4.荣获过国家级或国际竞赛奖项；</p>\n<p>5.持有国际或国家权威机构认证的法律、金融、会计等职业的资格证书；</p>\n<p>6.担任过校级学生会干部或在全国学联组织任职；</p>\n<p>7.外语能力特别突出且在重大活动中担任过翻译人员；</p>\n<p>8.拥有科技创新型企业实习实践经验。</p></div>",
