    "notes": "岗位职责：\n1、本岗位分为前端、后端、大数据三个方向，负责公司业务系统及大数据应用从前端UI、后端服务到数据pipeline的端到端设计、开发和迭代维护，确保系统的高可用、高扩展性和高性能；持续优化系统性能，包括前端加载速度、后端服务响应能力及大数据处理效率；攻克技术难题，保障系统稳定安全运行。参与制定并遵循开发规范、流程与标准；编写高质量的技术文档，积极跟进并引入前沿技术，提升团队研发效能。\n2、前端方向：与UI/UX设计师紧密协作，负责Web前端页面的开发、优化与维护，确保产品界面美观、交互流畅、兼容性强，并持续提升用户体验。\n3、后端方向：设计并实现稳健、高效的后端微服务架构，参与技术选型与核心模块开发，解决复杂的业务逻辑和技术难题。\n4、大数据方向：参与数据中台与数据仓库的建设，运用大数据工具（如Spark,Flink）进行数据清洗、加工和分析；开发数据主题报表和可视化看板，将数据洞察转化为商业价值。\n\n\n任职条件：\n1、大学本科及以上学历应届毕业生，有相关经验、计算机相关专业优先。本岗位按前端、后端、大数据三个方向招聘，满足其中一个方向即可。\n2、前端方向：熟悉HTML,CSS,JavaScript，有Vue.js、Node.js开发经验。\n3、后端方向：熟悉Java或Python等一门面向对象编程语言，熟悉前后端交互，熟悉Spring,SpringBoot,Springcloud，Hibernate/MyBatis/JPA等主流框架，了解基础的数据结构和算法。\n4、大数据方向：熟练掌握SQL编程和优化经验，熟悉关系型数据库如Oracle,Mysql等。熟悉ETL、报表、调度等多种产品机制，有BI分析工具使用经验者优先。\n5、具备良好的团队协作精神和沟通能力。",
