    "notes": "工作职责:\n1、在职责上对项目经理负责，对所服务的项目负责;\n2、在技术服务项目经理的指导下，完成每项工程的现场技术服务工作;\n3、现场协调有关工作，如接货、退货、单等程序工作:4、及时发现技术配套中的需要更改、变动等技术数据，及时与部门、营销部门及业务员等联系，现场解决技术问题。 \n4、协助部门解决涂料有关问题、事故；\n5、按照部门要求制作施工报告及其他报告并及时归档，总结施工指导的经验、不足和改进措施，并对公司相关部门提出改进建议;\n6、负责征求客户对公司的意见和建议，汇总后及时反馈给公司，针对客户意见提出改进意见;\n7、负责收集从施工现场反馈的竞争对手的技术及商业信息，给技术中心提供涂料改进意见，同时将相关信息提供给市场策划部;\n8、严格按照公司章程和制度，遵守工作驻地单位的纪律和有关安全制度，自检自律、树立公司良好形象;\n9、领导交办的临时工作。\n任职要求:\n(一)教育背景:本科及以上学历，化工相关专业。\n专业能力:有一定的涂料知识。-)\n(三)职业素养:具备良好的沟通协调、团队合作精神，工作细致、严谨，具有高度的工作热情和责任感。",
