    "notes": "岗位职责\n1、结合相关具体业务需求，负责公司部门内数字化、智能化转型战略的规划与落地，统筹数智化项目建设与推进；\n2、主导数智化平台的建设与运营，完善数据治理体系；\n3、负责大数据、人工智能等新技术在航运业务、通用管理业务场景中的应用研究，推动业务模式创新；\n4、统筹数智化相关系统的需求分析、方案设计与实施落地，协调内外部资源保障项目交付；\n5、跟踪行业数智化发展趋势，为公司数智化决策提供支撑。\n\n任职条件\n1、本科及以上学历，计算机、软件工程类、大数据、数理统计类、电子信息类、数学、统计学等相关专业优先；\n2、熟悉数据治理、大数据、人工智能等前沿技术，具备基本的技术认知、开阔的行业视野，能够结合业务场景推动技术落地与落地赋能；\n3、具备优秀的逻辑思维、统筹规划和跨部门协同能力，可推进数智化营销项目从方案规划到落地迭代的全流程工作；\n4、拥有良好的数据敏感度与数据分析能力，擅长通过数据复盘问题、提炼规律、输出优化方案，能够用AI工具做材料辅助、数据统计分析、报表自动化、简单流程优化；\n5、工作积极主动、责任心强，具备优秀的沟通表达能力、团队协作意识，具备良好的抗压能力。",
