    "examInfo": "",
    "companyScale": "500-1000人",
    "notes": "岗位职责：\n一、需求理解与方案设计\n与业务、产品一起梳理业务场景及 AI 应用场景，完成需求调研、问题定义与可行性评估；参与产品与技术方案设计，输出需求/设计文档，推动方案落地实施。\n二、系统与功能研发\n负责 AI 应用系统或产品的前端、后端及全栈开发：\n后端——搭建大模型应用服务、业务接口与数据库服务；\n前端——开发 AI 交互、业务可视化页面；\n全栈——负责产品页面、交互功能与接口的开发维护，参与数据库设计与前后端联调；\n运用 AI 辅助编程工具提升研发效率。\n三、方向性专项研发（按部门侧重，具备其一即可）\nAI 应用与大模型工程：完成模型方案选型与实现、数据处理、微调与推理优化，搭建 LLM / RAG / 向量库 / Agent 应用；\nAI 平台与智能体：参与企业级 AI 智能体平台的功能设计、开发、联调测试与交付；\n测试开发与质量保障：设计功能/性能/兼容性用例，建设 AI 驱动测试基座与多 Agent 协作测试体系。\n四、工程落地与性能调优\n完成代码实现、测试部署、性能调优与线上故障排查，保障算法/应用服务的高可用与稳定运行；参与技术调研、代码评审与开发规范沉淀。\n五、协作与持续迭代\n与产品、算法、测试、硬件及业务团队紧密协作，跟踪关键指标与业务反馈，负责上线后的运行维护、问题响应与版本迭代。\n\n岗位要求：\n一、学历与专业\n本科及以上学历，硕士研究生优先；含应届毕业生及在校生（27 届优先）；\n计算机科学与技术、软件工程、人工智能、信息管理、电子信息、通信、自动化、应用数学/统计学、数据科学等相关专业。\n二、编程与工程基础\n掌握 Java/Python/Go/C++/Node.js 等至少一种后端开发语言，具备良好的编程基础与工程实践能力；熟悉数据结构、计算机网络、数据库等基础知识；\n熟悉 Spring Boot、MyBatis 等开发框架，了解 Oracle/MySQL/Redis 等数据库的使用与优化，具有复杂 SQL 编写与框架搭建经验者优先；\n掌握 HTML/CSS/JavaScript/TypeScript，精通 Vue/React 等至少一种前端框架，可独立完成业务页面与交互功能开发；\n熟悉 Linux 环境及常用命令，掌握 Docker 等容器化工具，了解 Git、云服务等常用开发工具。\n三、AI 与大模型能力\n熟悉大模型、AI 技术基础，掌握 PyTorch/TensorFlow/Transformers 等框架；熟悉 RAG、向量数据库、Embedding、LangChain/Agent 等技术者优先；\n精通线性代数、概率论、微积分、最优化理论等数学基础（AI/算法方向）；\n了解 AI 辅助编程（Vibe Coding），能深度使用 Cursor、GitHub Copilot、Claude Code 等主流 AI 代码助手，掌握高质量 Prompt 编写技巧，提升研发与交付效率；\n有 AI 应用落地经验（模型选型、数据处理、性能优化、效果评测）者优先。\n四、加分项（优先）\n具有从 0 到 1 的产品/系统研发或 AI 应用落地经验；\n有开源项目贡献、竞赛或完整项目经历；\n熟悉信创软件开发，或有航运数字化/海事行业项目、实习经历；\n有 LLM/Agent 评测体系或测试基座建设经验（测试方向）。\n五、通用素质\n良好的逻辑思维与问题解决能力，能独立分析、攻关技术难点；\n良好的沟通协调能力与团队协作精神，可在产品、开发、运维等角色间灵活切换；\n学习能力与责任心强，对技术有热情，能快速学习并应用前沿技术。",
