    "applyLink": "https://coscoshipping.iguopin.com/job/detail?id=218782098796839188",
    "noticeLink": "https://coscoshipping.iguopin.com/job",
    "examInfo": "",
    "companyScale": "500-1000人",
    "notes": "岗位职责：\n1. 需求理解与算法方案设计\n深入理解业务实际场景需求，完成问题定义与可行性评估，提供算法层面的整体解决方案，并推动方案落地实施。\n2. 算法研发与优化\n负责机器学习、深度学习及大模型相关算法的研发与优化，包括数据准备与处理、特征工程、模型架构设计、模型训练与调优、效果评测与持续迭代；针对复杂场景持续优化算法鲁棒性与精度。\n3. 方向性专项研发（按部门侧重）\n结合部门业务方向承担相应专项研发，具备以下任一方向能力：\n大模型与智能体方向：基于大模型技术生态开展应用与智能体开发，实现自主决策与任务执行；\n机器视觉方向：负责基于机器视觉或激光点云的目标检测、跟踪与轨迹分析，开发行为逻辑分析模块，协同硬件团队完成算法在边缘设备的移植与加速；\n数据分析与数据产品方向：构建指标与数据分析体系，运用机器学习、深度学习及大模型技术为业务决策与产品方向提供核心支持。\n4. 工程落地与性能调优\n参与算法从原型开发到工程落地的全流程，完成代码实现、测试部署、性能调优与线上问题排查，保障算法服务的高可用与稳定运行；参与技术调研、代码评审与开发规范沉淀。\n5. 跨团队协作与持续迭代\n与产品、研发、测试、硬件及业务团队紧密协作，跟踪关键指标与业务反馈，主动探索业务机会点，推动算法与产品持续迭代优化。\n\n岗位要求：\n一、学历与专业\n本科及以上学历，硕士研究生优先；统招硕士及以上在校生（27届优先）亦可；\n计算机、人工智能、软件工程、自动化、控制工程、数据科学、应用统计、大数据、数学等相关理工科专业。\n二、算法与技术基础\n具备扎实的算法与数据结构基础，精通机器学习、深度学习相关理论与主流框架，熟悉大模型技术原理；\n精通 C++，熟悉 STL、多线程、内存管理及性能优化；熟练掌握 Python，具备优秀的编码风格与面向对象思想，熟悉异步编程、多线程编程；\n熟悉 PyTorch、TensorFlow 等主流深度学习框架，以及 Transformer、LangChain、vLLM 等大模型技术生态，了解 Dify、Coze 等大模型工作流开发；\n具备数据获取、处理、建模分析、可视化能力，熟练掌握 SQL，了解 BI 工具者加分。\n三、方向性技能（按部门侧重，具备其一即可）\n大模型/智能体：有智能体开发与大模型应用落地经验，有实际 Python 项目落地经验，熟练使用 Docker、Kubernetes 部署；\n机器视觉：熟练掌握 OpenCV 等工具库，了解特征提取、光流法、卡尔曼滤波等传统图像处理技术，有单目测距、相机标定、传感器融合（视觉+激光点云/AIS/IMU）等经验者优先；\n数据分析与建模：具备将分析框架沉淀为数据模型、数据产品的能力，能通过数据分析为业务决策提供支持。\n四、加分项（优先）\n有开源项目贡献经验；\n有 AI 视频识别、大模型智能体框架等前沿方向的调研与落地经验；\n有完整的项目落地经验（含实习/科研项目）。\n五、通用素质\n良好的逻辑分析与问题解决能力，能独立攻关技术难点；\n良好的沟通协调能力与团队协作精神，较强的学习能力和责任心，有积极主动的探索精神；\n强烈的技术热情，能快速学习并应用前沿技术。",
