    "notes": "岗位职责\n1. 需求调研与市场分析\n负责航运业务场景及公司产品的需求调研，开展市场与竞品研究，敏锐把握用户痛点与需求，收集客户及内部使用方反馈，评估产品与市场（含 AI 应用场景）的契合度，为产品立项与方向决策提供依据。\n2. 产品规划与设计\n制定产品战略与路线图（Roadmap），定义产品需求与成功指标；提出产品设想与方案，撰写 PRD（产品需求文档）并制作原型图；结合航运各细分场景推进 AI 标准化体系建设，统筹通用 AI 平台能力建设，沉淀可复用的产品与能力框架。\n3. 项目管理与推进\n统筹 AI 产品项目全流程管理，平衡业务、技术与用户需求，协调各类资源，推动产品开发、落地实施，以及项目端 AI 产品的交付与交付后优化。\n4. 跨团队协作与沟通\n排定功能优先级，协调研发、设计、算法、市场、销售等各利益相关方，推动产品愿景与方案在组织内高效落地执行。\n5. 产品持续优化\n跟踪产品上线后的数据表现与用户反馈，开展效果评估，推动产品持续迭代改进，负责产品的全生命周期管理。\n岗位要求\n1.学历与专业\n硕士研究生及以上学历，理工科专业优先，包括计算机、软件工程、信息管理、交通运输、航海/船舶工程等；\n熟悉大模型、AI 技术基础；有航运数字化相关研究或项目经历者优先。\n2.专业能力\n需求分析：擅长需求分析与产品文档撰写，能输出高质量 PRD；\n产品设计：具备优秀的 UI/UX 设计能力与简化复杂业务逻辑的能力，能将复杂逻辑转化为简洁优雅的用户体验；\n数据驱动：具备数据分析能力，能通过数据指导产品决策；\n协同推进：具备跨团队协同能力，有较强的项目管理与资源协调能力。\n3.工具技能\n原型与设计：熟练使用 Figma 或 MasterGo 等主流设计工具，能独立完成从信息架构、交互流程到高保真原型设计的全过程；熟悉 Axure、墨刀等原型设计工具；\n编程与 AI 工具：熟练使用 Python，深度使用 Cursor、Claude Code 等 AI 编程工具者优先；\n办公软件：熟练使用 PPT、Excel、Word 等各类办公软件。\n4.加分项（优先）\n具有从 0 到 1 搭建产品设计系统的经验；\n具有基于 LLM 的应用从 0 到 1 的创业或核心开发经验；\n熟悉并能清晰阐述海外前沿 LLM 的能力边界与适用场景；\n有国内外知名互联网或科技公司的实习/工作经验。\n5.通用素质\n良好的逻辑思维能力、沟通表达能力与团队合作精神；\n优秀的抗压能力与沟通协调能力；\n严谨好学。",
