    "notes": "岗位职责：\n一、测试需求与用例设计\n负责航运业数智化系统的功能、性能、兼容性测试，参与需求分析，设计覆盖航运复合型业务场景的测试用例。\n二、测试执行与缺陷管理\n执行测试并记录缺陷，跟踪修复进度，负责大型项目的交付上线与质量把关。\n三、测试报告与技术文档\n编写测试报告及相关技术文档，输出测试结论，为产品上线提供质量依据。\n四、自动化与 AI 测试能力建设（资深方向侧重）\n参与自动化测试脚本开发及 AI 测试工具应用，运用 AI 工具完成用例智能生成、脚本自动化产出、测试执行与结果分析；建设 AI 驱动测试基座，构建多 Agent 协作测试系统，封装业务 Skill/MCP 能力。\n五、跨团队协作与持续优化\n跨部门沟通协调、现场问题处置，跟踪缺陷闭环并推动质量持续改进。\n\n岗位要求：\n一、学历与专业\n本科及以上学历；应届毕业生（校招）或 5 年以上测试开发经验、含 2 年以上中大型测试架构设计与落地经验者（社招）均可；\n人工智能、计算机、航运物流、通信、自动化等相关专业。\n二、测试基础\n掌握软件测试基础知识，熟悉黑盒/白盒测试方法，能独立设计功能/性能/兼容性测试用例；\n熟悉 MySQL/Oracle 等数据库基本操作，了解 JMeter、Selenium、Postman 等主流测试工具。\n三、编程与自动化能力\n至少掌握一种编程语言（Python/Java）；\n具备测试脚本自动化产出与执行分析能力；有自动化测试框架搭建经验者优先。\n四、AI 测试与前沿能力\n对 AI 辅助测试（用例生成、脚本产出、结果分析）有浓厚兴趣，能熟练运用 AI 工具提升测试效率；\n熟悉主流大模型能力特点，具备 LLM/Agent 评测体系或 Testing Harness 建设经验者优先；了解 LangGraph/AutoGen/MCP 等 Agent 框架，理解 Context Engineering、RAG、Planning、Reflection 等核心范式；\n有 AI 驱动测试基座、多 Agent 协作测试系统、业务 Skill/MCP 封装经验者优先。\n五、通用素质\n逻辑清晰，具备良好的沟通能力与团队协作意识，细致耐心、责任心强；\n具备出色的跨部门沟通协调能力及现场问题处置能力，能承受项目交付节奏压力。\n加分项（优先）：有航运智能化项目交付验收、云产品测试或自动化测试框架搭建经验。",
