    "notes": "岗位职责：\n1.负责集装箱制造数字化运营平台、工业物联网、MES、工业自动化系统、SDN工业网日常运维、实时监控与故障闭环处理，夯实产线数字化底座，保障智能化生产业务稳定高效运行；\n2.参与企业智能制造升级工作，协助推进AI视觉检测、生产数据智能分析、智能运维算法模型的场景落地、测试调试与应用优化，助力集装箱生产环节智能化提质增效；\n3.搭建并优化信息化自动化运维体系，依托AI运维工具、自动化脚本实现设备巡检、系统监控、故障预警的智能化升级，替代传统人工运维模式，提升运维数字化、智能化水平；\n4.聚焦集装箱制造数字化转型需求，开展工业互联网、AI智能制造新技术调研与场景试点，梳理生产、工艺、质检等业务痛点，协助制定智能化优化方案，推进企业技术创新落地；\n5.严格落实网络安全与等保合规要求，负责智能制造、AI应用系统的权限管控、数据安全审计、风险排查与漏洞整改，保障工业数据与智能系统安全合规运行；\n6.对接各生产业务部门，提供智能系统、数字化应用技术支撑，参与智能系统应急保障，快速处置产线自动化、智能化突发故障，保障生产连续性。\n任职要求：\n1.本科及以上学历，计算机相关专业；\n2.具备扎实的计算机、工业数字化基础理论，对制造行业数字化转型有浓厚探索兴趣；\n3.熟悉Windows/Linux服务器、虚拟化、私有云、工业网络架构基础，了解MES、工业智能系统架构，具备AI视觉、大数据分析、智能运维工具实操经验者优先；\n4.掌握人工智能、工业数字化、自动化运维基础原理，能够辅助完成AI模型落地、智能场景测试与数据优化相关基础工作，具备技术创新思维；\n5.具备良好的逻辑分析与问题排查能力、跨部门协同沟通能力，可高效对接生产智能化升级工作；\n6.遵守企业保密制度及内控管理规范，工作严谨踏实、责任心强，具备较强的新技术学习能力和创新意识，可适应制造产线智能化系统应急保障工作。",
