    "notes": "【岗位职责】\n1. 合同合规审核与管理：协助负责公司各类合同、法律文书的起草、修订、初审及归档工作，精准排查法律风险，提出合规审核意见，筑牢业务合规经营防线。\n2. 法律事务处理：依托专业核心能力，协助处置各类合同纠纷、货运争议等专项问题；协助对接海事法院、司法机关、合作律所，全程跟进公司各类诉讼、仲裁、调解案件。\n3. 合规制度建设与宣贯：协助梳理、修订公司合规管理制度及风控流程；跟进国内外海事、航运、跨境贸易相关法律法规、政策及行业规则更新；开展内部合规宣导，为各业务部门提供日常法律咨询与合规指导。\n\n【任职条件】\n1. 大学本科及以上学历应届毕业生；\n2. 海商法、国际法、民法、法学专业；\n3. 专业基础扎实，熟悉国际航运公约、海事法律、跨境贸易法律核心规则；\n4. 具备优秀的英文读写、翻译能力；\n5. 逻辑严谨、风险敏感度高，具备扎实的法律文书写作、案件梳理、风险分析能力；熟练使用Office办公软件，擅长资料整合、台账搭建、报告撰写。",
